import json,re,subprocess
d=json.load(open(".ufo/waves/round-14/repair/integration-verification.json"))
for name,pat in d["safety_scan"]["patterns"].items():
 hits=[]
 for p in d["safety_scan"]["scope"]:
  text=subprocess.check_output(["git","show",d["implementation"]+":"+p],text=True)
  n=len(re.findall(pat,text,re.M))
  if n: hits.append({"path":p,"count":n})
 print(name,hits)
